', 'Penggunaan botol air minum (mengurangi 1-10, bermain bowling ) dan pengurangan sebagai pemisah', '{\"a\":\"anak lebih aktif karena melalui permainan dan kegiatan yang menyenangkan\",\"b\":\"lebih percaya diri dan terlibat aktif dalam proses pembelajaran\",\"c\":\"Lebih mudah menyerap dan memahami konsep materi yang disampaikan\",\"d\":\"peserta didik mampu memecahkan masalah melalui permainan dan menggunakan alur gembira\",\"e\":\"Komunikasi dan kolaborasi lebih aktif dan interaktif dalam proses pembelajaran\"}', NULL, NULL, NULL, 'Supiati', 'SDN Leseng', 'Peserta Matematika GEMBIRA', 'Rizki Rachmadaniar', '-', '2026-10-28', NULL, NULL, NULL),
(12, 'GEMBIRA', NULL, 13, '2026-10-24', 'YAYUK KURNIAWATI', 'Rekan sejawat', 'Rijan Nurbayan', 'Selesai', '{\"program\":\"Matematika GEMBIRA\",\"nama_guru\":\"YAYUK KURNIAWATI\",\"nama_sekolah\":\"SDN 02 WOJA\",\"kelas_fase\":\"IIb\",\"topik_materi\":\"Mengenal Mata Uang\",\"jabatan_penilai\":\"Rekan sejawat\",\"tanggal_monev\":\"2026-10-24\",\"sumber_data_bukti\":\"HASIL OBSERVASI DAN WAWANCARA\",\"jawaban_terbuka\":{\"1\":\"Menyenagkan dan mendapat ilmu baru\",\"2\":\"tidak ada kendala\",\"3\":\"dari pembelajaran abstrak ke pembelajaran yang menggunakan media pembelajaran dan alat secara kongkrit\",\"4\":\"sudah bis menerapkan alur gembira dalam pembelajaran matematika\",\"5\":{\"a\":\"peserta didik lebijh aktif dalam menerima pelajaran\",\"b\":\"siswa lebih percaya diri dalam berexplorasi dan menyampaikan pemikirannya\",\"c\":\"siswa sudah lebih memahami konsef dari yang abstrak ke yang kongkrit\",\"d\":\"anak sudah bisa memecahkan soal soal matematika\",\"e\":\"mampu bekerjasama dalam kelompok\"},\"6\":\"ada anak lebih bisa berhitung dengan baik\",\"7\":\"semoga kegiatannya lebih bagus lagi dan berlanjut dari fase A ke fase B dan C\"}}', 'NO', '2026-10-29 00:33:23', '2026-10-29 00:33:23', 'Menyenagkan dan mendapat ilmu baru', 'tidak ada kendala', 'dari pembelajaran abstrak ke pembelajaran yang menggunakan media pembelajaran dan alat secara kongkrit', 'sudah bis menerapkan alur gembira dalam pembelajaran matematika', '{\"a\":\"peserta didik lebijh aktif dalam menerima pelajaran\",\"b\":\"siswa lebih percaya diri dalam berexplorasi dan menyampaikan pemikirannya\",\"c\":\"siswa sudah lebih memahami konsef dari yang abstrak ke yang kongkrit\",\"d\":\"anak sudah bisa memecahkan soal soal matematika\",\"e\":\"mampu bekerjasama dalam kelompok\"}', NULL, NULL, NULL, 'YAYUK KURNIAWATI', 'SDN 02 WOJA', 'Rekan sejawat', 'Rijan Nurbayan', '-', '2026-10-24', NULL, NULL, NULL),
